// Prompt W4 checkpoint C7: lib/sources.ts strips the trailing "Sources" block only on an exact match of render_citations'
// output (fixtures generated by that server function: e2e/fixtures/render_citations.json). Run: node scripts/check_sources_strip.mjs
import fs from "node:fs";
import { stripSourcesBlock } from "../lib/sources.ts";

const cases = JSON.parse(fs.readFileSync(new URL("../e2e/fixtures/render_citations.json", import.meta.url), "utf8"));
let bad = 0;
for (const c of cases) {
  const { text, stripped } = stripSourcesBlock(c.rendered, c.has_sources);
  const expectStrip = c.has_sources && /\n\nSources\n\[1\] /.test(c.rendered);
  const ok = stripped === expectStrip && (!stripped || !text.includes("\nSources\n")) && (stripped || text === c.rendered);
  if (!ok) bad++;
  console.log(`${ok ? "ok  " : "FAIL"} ${c.name.padEnd(26)} stripped=${stripped} expected=${expectStrip}`);
  // a block that is NOT the server's shape (the model's own "Sources" text) is never cut
  const own = stripSourcesBlock("Answer.\n\nSources\n[1] looks like one but is the model's own text\nmore prose", true);
  if (own.stripped) {
    bad++;
    console.log("FAIL a non-matching block was stripped");
  }
}
console.log(`${cases.length} fixtures, ${bad} failures`);
process.exit(bad ? 1 : 0);
